"/us/en/portfolios/medical-surgical-equipment/incontinence-management/barrier-care": {"template":"specialty","metadata":{"title":"Barrier Care","pageTitle":null,"description":"Incontinent patients are at increased risk for incontinence-associated dermatitis (IAD), a condition that can also contribute to pressure injuries.¹ Stryker’s medical barrier cream cloths help support consistent skin protection by combining cleansing, moisturizing and barrier application in one step—helping clinicians address key risk factors while streamlining care.","image":"/content/dam/stryker/sage/products/barrier-cream-cloths/images/Sage-Comfort-Shield-Barrier-Cream-Cloths-thumbnail.jpg","imageAlt":"Sage Comfort Shield Barrier Cream Cloths","tags":["stryker:specialty/barrier-care","stryker:content-type/specialty","stryker:capability/incontinence-management","stryker:content-type/hcp_content","stryker:portfolio/medical-and-surgical-equipment"],"originallyPublished":"2026-05-29T19:50:32.000Z","lastPublished":"2026-05-29T19:50:32.000Z","contentID":"SAGE-CSBC-SYK-3098728_REV-0_en_us"},"anchors":[],"disclaimer":"<p><b>References</b></p>\r\n<p>1. Gray M, Guiliano K, Incontinence-Associated Dermatitis, Characteristics and Relationship to Pressure Injury A Multisite Epidemiologic Analysis, Journal of Wound Ostomy Continence Nursing, January/February 2018;45(1):63-7.</p>","forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
