"/us/en/portfolios/medical-surgical-equipment/integration-and-connectivity/hospital-enterprise-software": {"template":"specialty","metadata":{"title":"Hospital enterprise software","pageTitle":null,"description":"Our hospital enterprise software offering securely integrates information systems with your compatible devices, and allows you to stay connected both inside your facility and to the outside world. Our platform allows the flexibility to archive, edit and share surgical content. In addition, it allows you to communicate important information internally and externally to maximize educational opportunities and expand your continuity of patient care.","image":"/content/dam/stryker/portfolios/medical-surgical/integration-and-connectivity/images/Hospital-Enterprise-thumbnail.jpg","imageAlt":"Hospital enterprise software","tags":["stryker:content-type/specialty","stryker:capability/integration-and-connectivity","stryker:specialty/hospital-enterprise-software","stryker:portfolio/medical-and-surgical-equipment","stryker:content-type/hcp_content"],"originallyPublished":"2023-02-06T22:37:01.000Z","lastPublished":"2025-10-30T22:37:01.000Z","contentID":"ENDO-GSNPS-SYK-1839050"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/portfolios/medical-surgical-equipment/integration-and-connectivity/or-integration": {"template":"specialty","metadata":{"title":"OR integration","pageTitle":null,"description":"Transform your operating room with our OR integration by seamlessly integrating compatible surgical devices to simplify your workflow and maximize efficiency.  See and do more in your surgical environment with our offering of high-quality display systems and touch panel-controlled room cameras.   \r\n","image":"/content/dam/stryker/portfolios/medical-surgical/integration-and-connectivity/images/OR-integration-thumbnail-v2.jpg","imageAlt":"OR integration","tags":["stryker:content-type/specialty","stryker:capability/integration-and-connectivity","stryker:specialty/OR-integration","stryker:portfolio/medical-and-surgical-equipment","stryker:content-type/hcp_content"],"originallyPublished":"2023-02-06T22:37:01.000Z","lastPublished":"2025-10-30T22:37:01.000Z","contentID":"ENDO-GSNPS-SYK-1839050"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/portfolios/medical-surgical-equipment/navigation/cranial": {"template":"specialty","metadata":{"title":"Cranial","pageTitle":null,"description":"Our simplified solutions to incorporate navigation into neurosurgical procedures, from pre-op planning to intra-operative guidance and control, have been designed to meet the demands in today’s operating room and help deliver better patient outcomes.","image":"/content/dam/stryker/portfolios/medical-surgical/navigation/cranial/images/Thumbnail_NavCranial.png","imageAlt":null,"tags":["stryker:specialty/cranial","stryker:content-type/specialty","stryker:portfolio/medical-and-surgical-equipment","stryker:capability/navigation","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2018-08-28T14:58:17.000Z","contentID":"9100-004-800 Rev. None"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/portfolios/medical-surgical-equipment/navigation/ent": {"template":"specialty","metadata":{"title":"ENT","pageTitle":null,"description":"We offer solutions to incorporate navigation into ENT procedures. From standard FESS procedures to more complex revision sinus surgeries, our products deliver intraoperative guidance and control to meet the demands of today’s operating room with the goal of better patient outcomes.","image":"/content/dam/stryker/portfolios/medical-surgical/ent/images/Thumbnail_ENT.png","imageAlt":null,"tags":["stryker:content-type/specialty","stryker:specialty/ent-navigation","stryker:portfolio/medical-and-surgical-equipment","stryker:capability/navigation","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2022-03-02T16:33:37.000Z","contentID":"9100-004-800 Rev. 1"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
