"/us/en/portfolios/medical-surgical-equipment/smart-hospital/clinical-communication": {"template":"specialty","metadata":{"title":"Clinical communication","pageTitle":null,"description":"Unify the people and information needed to deliver patient care and simplify communication. Create a richer, more human-centered connection for care teams, patients and their loved ones. Our solutions can be tailored for your specific needs, from urgent, voice communication when seconds matter, to secure messaging, closed-loop EHR workflows and more.","image":"/content/dam/stryker/portfolios/medical-surgical/smarthospital-platform/clinical-communication/clinical-communications_hero_nowaves_675x450.jpg","imageAlt":"Stryker's clinical communication devices, mobile screens and hands-free badges","tags":["stryker:content-type/specialty","stryker:content-type/hcp_content","stryker:portfolio/medical-and-surgical-equipment","stryker:capability/smart-hospital","stryker:specialty/clinical-communication"],"originallyPublished":"2026-02-02T19:35:42.000Z","lastPublished":"2026-02-02T19:35:42.000Z","contentID":"AC-GSNPS-SYK-2604102_REV-0_en_us"},"anchors":[],"disclaimer":"<p>The names and characters presented throughout are entirely fictious. Any similarity to names or incidents is entirely coincidental.</p>","forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
