"/us/en/portfolios/medical-surgical-equipment/surgical-suction/surgical-smoke-evacuation": {"template":"specialty","metadata":{"title":"Surgical smoke evacuation","pageTitle":"Surgical smoke evacuation","description":"Our smoke solutions line-up is designed for both clinical utility and user safety. With a full portfolio of retractors, tissue dissectors, and aspirators with smoke evacuation capability and the two best smoke evacuation units on the market, we can help you enhance surgical efficiency and staff wellbeing while creating a smoke-free environment for any procedure room.","image":"/content/dam/stryker/portfolios/medical-surgical/surgical-suction/Thumbnail_Surgical Smoke.jpg","imageAlt":null,"tags":["stryker:content-type/specialty","stryker:portfolio/medical-and-surgical-equipment","stryker:capability/surgical-suction","stryker:specialty/surgical-smoke-evacuation","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2020-07-27T15:22:34.000Z","contentID":"9100-004-748 Rev. None"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/portfolios/medical-surgical-equipment/surgical-visualization/camera-systems": {"template":"specialty","metadata":{"title":"Camera systems","pageTitle":"Camera systems","description":"High-definition endoscopic camera systems that are used to produce still and video images in the surgical field during surgical endoscopic procedures. The system is sensitive in the visible and infrared spectrum. The optical image is transferred from the surgical site to the camera head by a variety of rigid and flexible scopes which are attached to the camera head. The system consists of a camera control unit (CCU) and a camera head with an integral cable that connects to the CCU.","image":"/content/dam/stryker/portfolios/medical-surgical/surgical-visualization/images/0724/Thumb-Cameras.jpg","imageAlt":"Camera Systems","tags":["stryker:capability/surgical-visualization","stryker:content-type/specialty","stryker:specialty/camera-systems","stryker:portfolio/medical-and-surgical-equipment","stryker:content-type/hcp_content"],"originallyPublished":"2023-02-06T20:48:51.000Z","lastPublished":"2024-08-14T20:48:51.000Z","contentID":"Literature Number: 1000902492, Rev. A"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
