"/us/en/portfolios/neurotechnology-spine/cranial/bioreabsorbables": {"template":"specialty","metadata":{"title":"Bone cements","pageTitle":null,"description":"Our market leading Hydroxyapatite bone cements for cranial applications provide you with flexible delivery systems to assist with OR efficiency and patient outcomes.","image":"/content/dam/stryker/craniomaxillofacial/products/directinjecton-demandhacement/images/Thumbnail_DirectInject.png","imageAlt":null,"tags":["stryker:content-type/specialty","stryker:portfolio/neurotechnology","stryker:capability/cranial","stryker:specialty/cranial-bioresorbables","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2018-07-18T09:50:06.000Z","contentID":"CMF-WC-36_Rev.None_15561"},"anchors":[],"disclaimer":"<p>In the US, based on internal estimates. Sales data on file.<br>\r\n</p>","forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
