"/us/en/portfolios/orthopaedics/craniomaxillofacial/aesthetics": {"template":"specialty","metadata":{"title":"Aesthetics","pageTitle":null,"description":"Having the very best products and service is a critical component of performing aesthetic surgery. Our proven MEDPOR implants and world-renowned Colorado Needles are just the start of a portfolio of market-leading products. Combined with our unfailing service, we’re committed to helping you keep your aesthetic business the very best it can be.","image":"/content/dam/stryker/portfolios/orthopaedics/cmf-implants/images/Thumbnail_Aesthetic.png","imageAlt":null,"tags":["stryker:content-type/specialty","stryker:portfolio/orthopaedics","stryker:capability/cmf-implants","stryker:specialty/aesthetics","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2018-11-19T16:10:06.000Z","contentID":"CMF-WC-28_Rev. None_14666 "},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/portfolios/orthopaedics/craniomaxillofacial/orthognathic": {"template":"specialty","metadata":{"title":"Orthognathic","pageTitle":null,"description":"Correcting skeletal irregularities, whether for functional or aesthetic reasons, is a big deal in a patient’s life, and we offer a complete portfolio of products to support you. Our planning and surgical tools along with our 2D and 3D plates provide you the utmost confidence to plan and execute each case, so that you’re well equipped with the tools to do your heroic work.","image":"/content/dam/stryker/portfolios/orthopaedics/cmf-implants/images/Thumbnail_Orthognathic.png","imageAlt":null,"tags":["stryker:content-type/specialty","stryker:portfolio/orthopaedics","stryker:capability/cmf-implants","stryker:specialty/orthognathic","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2018-11-19T16:09:49.000Z","contentID":"CMF-WC-28_Rev. None_14666 "},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/portfolios/orthopaedics/craniomaxillofacial/reconstruction": {"template":"specialty","metadata":{"title":"Reconstruction","pageTitle":null,"description":"Your facial reconstruction cases take herculean time, skill and dedication. From virtual pre-planning, to placing the final screw into a patient specific plate, we are alongside you every step of the way to help make your case as seamless as possible. Our market-leading products combined with our unfailing service provide an unmatched level of assurance for your entire perioperative experience.","image":"/content/dam/stryker/portfolios/orthopaedics/cmf-implants/images/Thumbnail_Reconstruction.png","imageAlt":null,"tags":["stryker:specialty/reconstruction","stryker:content-type/specialty","stryker:portfolio/orthopaedics","stryker:capability/cmf-implants","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2023-05-09T20:40:32.000Z","contentID":"CMF-WC-28_Rev. None_14666 "},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/portfolios/orthopaedics/craniomaxillofacial/trauma": {"template":"specialty","metadata":{"title":"Trauma","pageTitle":null,"description":"Stryker’s facial trauma products are the #1 most chosen products for facial trauma cases.¹ Our German-engineered products have a long history of quality and reliability and are backed by unparalleled service - attributes we believe are paramount in helping you achieve the very best outcomes for your patients.\r\n","image":"/content/dam/stryker/portfolios/orthopaedics/cmf-implants/images/Thumbnail_Trauma.png","imageAlt":null,"tags":["stryker:specialty/trauma","stryker:content-type/specialty","stryker:portfolio/orthopaedics","stryker:capability/cmf-implants","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2018-11-19T16:09:03.000Z","contentID":"CMF-WC-28_Rev. None_14666 "},"anchors":[],"disclaimer":"<p>¹In the US, based on internal estimates. Sales data on file.<br>\r\n</p>","forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/portfolios/orthopaedics/foot-and-ankle/ankle": {"template":"specialty","metadata":{"title":"Ankle","pageTitle":null,"description":"The ankle includes the tibia, talus and the fibula bones.","image":"/content/dam/stryker/portfolios/orthopaedics/foot-and-ankle/images/Header_Ankle.jpg","imageAlt":null,"tags":["stryker:capability/foot-and-ankle","stryker:content-type/specialty","stryker:portfolio/orthopaedics","stryker:specialty/ankle-foot-and-ankle","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2020-11-11T14:44:46.000Z","contentID":"OT-AWI-44, 08-2017"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
