"/us/en/portfolios/orthopaedics/foot-and-ankle/forefoot": {"template":"specialty","metadata":{"title":"Forefoot","pageTitle":null,"description":"The forefoot is made up of the five toes and their five corresponding metatarsals. Half of our body weight is supported by this anterior section of the foot.","image":"/content/dam/stryker/portfolios/orthopaedics/foot-and-ankle/images/header_forefoot.jpg","imageAlt":"Forefoot","tags":["stryker:capability/foot-and-ankle","stryker:content-type/specialty","stryker:portfolio/orthopaedics","stryker:specialty/forefoot","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2020-11-11T14:45:16.000Z","contentID":"OT-AWI-41, 08-2017"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/portfolios/orthopaedics/foot-and-ankle/hindfoot": {"template":"specialty","metadata":{"title":"Hindfoot","pageTitle":null,"description":"The hindfoot is the area around the heel. It’s primarily made up of the talus (ankle bone) and the calcaneus (heel bone).","image":"/content/dam/stryker/portfolios/orthopaedics/foot-and-ankle/images/Header_Hindfoot.jpg","imageAlt":null,"tags":["stryker:capability/foot-and-ankle","stryker:content-type/specialty","stryker:portfolio/orthopaedics","stryker:specialty/hindfoot","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2020-11-11T14:45:43.000Z","contentID":"OT-AWI-45, 08-2017"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/portfolios/orthopaedics/foot-and-ankle/midfoot": {"template":"specialty","metadata":{"title":"Midfoot","pageTitle":null,"description":"Serving as a shock absorber, the midfoot forms the arches of your feet. It connects the forefoot to the hindfoot.","image":"/content/dam/stryker/portfolios/orthopaedics/foot-and-ankle/images/header_midfoot.jpg","imageAlt":"Midfoot","tags":["stryker:capability/foot-and-ankle","stryker:content-type/specialty","stryker:portfolio/orthopaedics","stryker:specialty/midfoot","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2020-11-11T14:46:15.000Z","contentID":"OT-AWI-46, 08-2017"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/portfolios/orthopaedics/joint-replacement/hip": {"template":"specialty","metadata":{"title":"Hip","pageTitle":null,"description":"We offer market-leading hip replacement implants for total hip arthroplasty, including our primary and revision portfolios designed to offer you a wide variety of implants, instrumentation and muscle-sparing surgical approach options. ","image":"/content/dam/stryker/joint-replacement/images/Hero_JR_Hip_Replacement_2023.png","imageAlt":null,"tags":["stryker:content-type/specialty","stryker:portfolio/orthopaedics","stryker:specialty/hip-joint-replacement","stryker:capability/joint-replacement","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2023-04-07T16:35:09.000Z","contentID":"GSNPS-WC-33_27568, JR-GSNPS-PHOT-595035"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
