"/us/en/portfolios/orthopaedics/trauma-and-extremities/biologics/nerve-repair": {"template":"specialty","metadata":{"title":"Nerve repair","pageTitle":null,"description":"Our nerve portfolio consists of type I collagen conduits and wraps. They are designed to provide a protective layer around injured peripheral nerves and offer a resorbable and semi-permeable encasement to facilitate nerve repair.","image":"/content/dam/stryker/portfolios/orthopaedics/biologics/nerve-repair/nerve-repair-sm.jpg","imageAlt":null,"tags":["stryker:specialty/nerve-repair","stryker:capability/biologics","stryker:content-type/specialty","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2022-03-31T17:35:00.000Z","contentID":"CP-AWI-12, 07-2017"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/portfolios/orthopaedics/trauma-and-extremities/elbow--hand-and-wrist": {"template":"specialty","metadata":{"title":"Hand and wrist","pageTitle":null,"description":"When it comes to hand and wrist treatment we have you covered. Our comprehensive portfolio will fit your need to treat fractures, small joint arthroplasty, fusions and soft tissue procedures.","image":"/content/dam/stryker/trauma-and-extremeties/products/variaxhand/images/hand-wrist-image.png","imageAlt":null,"tags":["stryker:content-type/specialty","stryker:portfolio/orthopaedics","stryker:capability/trauma-and-extremities","stryker:specialty/hand-and-wrist","stryker:system/trauma-and-extremities/cannulated-screws","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2018-11-19T20:08:41.000Z","contentID":null},"anchors":[],"disclaimer":"<p>The SR MCP and PIP Arthroplasty System is sold as a HUMANITARIAN USE \r\nDEVICE in the US. The effectiveness of this device for this use has not \r\nbeen demonstrated.</p>\r\n<p>CP-AWI-13, 07-2017</p>","forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/portfolios/orthopaedics/trauma-and-extremities/hip-fracture": {"template":"specialty","metadata":{"title":"Hip and pelvis","pageTitle":null,"description":"When you require a variety of hip fracture and pelvic treatment options look no further. We have continued to develop our products utilizing the latest technologies to meet all of your needs in hip and pelvis reconstruction.","image":"/content/dam/stryker/trauma-and-extremeties/products/propelvis/images/pelvis-indication-image.jpg.png","imageAlt":null,"tags":["stryker:content-type/specialty","stryker:specialty/hip-and-pelvis","stryker:portfolio/orthopaedics","stryker:capability/trauma-and-extremities","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2019-03-19T15:33:51.000Z","contentID":null},"anchors":[],"disclaimer":"<p>CP-AWI-13, 07-2017</p>","forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/portfolios/orthopaedics/trauma-and-extremities/shoulder": {"template":"specialty","metadata":{"title":"Shoulder and elbow","pageTitle":null,"description":"We are committed to bringing you new technologies including shoulder replacements, elbow management systems, locked plating and nailing. You can be confident that our portfolio best suits your needs for today and tomorrow.\r\n","image":"/content/dam/stryker/portfolios/orthopaedics/foot-and-ankle/images/shoulder-image.png","imageAlt":null,"tags":["stryker:content-type/specialty","stryker:portfolio/orthopaedics","stryker:capability/trauma-and-extremities","stryker:specialty/shoulder-and-elbow","stryker:content-type/hcp_content"],"originallyPublished":null,"lastPublished":"2018-11-19T20:04:05.000Z","contentID":null},"anchors":[],"disclaimer":"<p>CP-AWI-13, 07-2017</p>","forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
